const PROVIDERS = [
  { name: 'nvidia-nim', url: 'https://integrate.api.nvidia.com/v1/chat/completions', key: process.env.NVIDIA_API_KEY, model: 'qwen/qwen2.5-coder-32b-instruct' },
  { name: 'groq', url: 'https://api.groq.com/openai/v1/chat/completions', key: process.env.GROQ_API_KEY, model: 'llama-3.3-70b-versatile' },
  { name: 'deepseek', url: 'https://api.deepseek.com/v1/chat/completions', key: process.env.DEEPSEEK_API_KEY, model: 'deepseek-chat' },
  { name: 'openrouter', url: 'https://openrouter.ai/api/v1/chat/completions', key: process.env.OPENROUTER_API_KEY, model: 'google/gemini-2.5-flash' }
];

export async function askLLM(messages: { role: string; content: string }[]) {
  for (const p of PROVIDERS) {
    if (!p.key) continue;
    try {
      const res = await fetch(p.url, {
        method: 'POST',
        headers: { Authorization: `Bearer ${p.key}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: p.model, messages, temperature: 0.15 }),
        signal: AbortSignal.timeout(12000)
      });
      if (res.ok) return { provider: p.name, data: await res.json() };
    } catch { /* intenta siguiente proveedor */ }
  }
  throw new Error('Todos los proveedores fallaron');
}

