#!/usr/bin/env node
// agent-bus-mcp.mjs — Regístralo en mcp.json para que agentes de distintos IDEs hablen entre sí
// Uso en mcp.json: { "agent-bus": { "command": "node", "args": ["./agent-bus-mcp.mjs"] } }
import fs from "node:fs";
import readline from "node:readline";

const BUS = process.env.AGENT_BUS_FILE || ".metahaters/agent-bus.jsonl";
fs.mkdirSync(".metahaters", { recursive: true });
if (!fs.existsSync(BUS)) fs.writeFileSync(BUS, "");

const tools = [
  {
    name: "send_agent_message",
    description: "Envía un mensaje o tarea a otro agente (ej. backend, frontend, qa, cursor, opencode)",
    inputSchema: {
      type: "object",
      properties: {
        from: { type: "string" },
        to: { type: "string" },
        message: { type: "string" },
        files: { type: "array", items: { type: "string" } }
      },
      required: ["from", "to", "message"]
    }
  },
  {
    name: "read_agent_inbox",
    description: "Lee los últimos mensajes dirigidos a este agente (o to=all)",
    inputSchema: {
      type: "object",
      properties: { agent: { type: "string" }, limit: { type: "number" } },
      required: ["agent"]
    }
  }
];

const send = (obj) => process.stdout.write(JSON.stringify(obj) + "\n");
const rl = readline.createInterface({ input: process.stdin });

rl.on("line", (line) => {
  if (!line.trim()) return;
  const req = JSON.parse(line);
  if (req.method === "initialize") {
    return send({ jsonrpc: "2.0", id: req.id, result: { protocolVersion: "2024-11-05", capabilities: { tools: {} }, serverInfo: { name: "metahaters-agent-bus", version: "1.0.0" } } });
  }
  if (req.method === "tools/list") {
    return send({ jsonrpc: "2.0", id: req.id, result: { tools } });
  }
  if (req.method === "tools/call") {
    const { name, arguments: args = {} } = req.params;
    if (name === "send_agent_message") {
      const entry = { ts: new Date().toISOString(), from: args.from, to: args.to, message: args.message, files: args.files || [] };
      fs.appendFileSync(BUS, JSON.stringify(entry) + "\n");
      return send({ jsonrpc: "2.0", id: req.id, result: { content: [{ type: "text", text: "Mensaje enviado a " + args.to }] } });
    }
    if (name === "read_agent_inbox") {
      const rows = fs.readFileSync(BUS, "utf8").trim().split("\n").filter(Boolean).map((l) => JSON.parse(l));
      const inbox = rows.filter((r) => r.to === args.agent || r.to === "all").slice(-(args.limit || 15));
      return send({ jsonrpc: "2.0", id: req.id, result: { content: [{ type: "text", text: JSON.stringify(inbox, null, 2) }] } });
    }
  }
});
